//! The schema sill ships (design/22 §9.2): every domain's `KeySpec`s, generated by
//! `#[derive(SettingsSchema)]`, written by `sill --write-schema <dir>`.

use ds_settings::schema::{AppId, FilePath, KeyPath, Page, Schema, SettingsSchema};

use crate::bar::BarSettings;
use crate::calendar::CalendarSettings;
use crate::control_center::ControlCenterSettings;
use crate::display::DisplaySettings;
use crate::dock::DockSettings;
use crate::hot_corners::HotCornersSettings;
use crate::idle::IdleSettings;
use crate::launcher::LauncherSettings;
use crate::menus::MenusSettings;
use crate::notifications::NotificationsSettings;
use crate::osd::OsdSettings;
use crate::power_menu::PowerMenuSettings;
use crate::screenshot::ScreenshotSettings;
use crate::scroll::ScrollSettings;
use crate::scrollbar::ScrollbarSettings;
use crate::session::SessionSettings;
use crate::spaces::SpacesSettings;
use crate::switcher::SwitcherSettings;
use crate::widgets::WidgetsSettings;
use crate::window::WindowSettings;

/// The keys whose struct sits on another page but which design/22 §5 puts on Power: the lock
/// grace answers sill's idle service, not the locker (§3.19). The derive gives a whole
/// struct one page, so [`schemas`] moves these keys after it.
pub const POWER_KEYS_ELSEWHERE: &[&str] = &["session.lock_grace_s"];

/// `schema` with every key named in `paths` moved to `page`.
fn on_page(mut schema: Schema, paths: &[&str], page: &Page) -> Schema {
    for key in &mut schema.key {
        let KeyPath(path) = &key.path;
        if paths.contains(&path.as_str()) {
            key.page = page.clone();
        }
    }
    schema
}

/// One schema per domain, in `ShellFile` order.
pub fn schemas() -> Vec<Schema> {
    vec![
        BarSettings::schema(),
        DockSettings::schema(),
        LauncherSettings::schema(),
        ScrollSettings::schema(),
        ScrollbarSettings::schema(),
        MenusSettings::schema(),
        SwitcherSettings::schema(),
        NotificationsSettings::schema(),
        ControlCenterSettings::schema(),
        SpacesSettings::schema(),
        DisplaySettings::schema(),
        OsdSettings::schema(),
        WindowSettings::schema(),
        PowerMenuSettings::schema(),
        on_page(
            SessionSettings::schema(),
            POWER_KEYS_ELSEWHERE,
            &Page::Power,
        ),
        WidgetsSettings::schema(),
        CalendarSettings::schema(),
        ScreenshotSettings::schema(),
        HotCornersSettings::schema(),
        IdleSettings::schema(),
    ]
}

/// The one `sill.settings.toml` the package installs: every domain's keys under app `sill`,
/// file `sill/settings.toml`.
pub fn schema() -> Schema {
    Schema {
        app: AppId("sill".to_owned()),
        file: FilePath("sill/settings.toml".to_owned()),
        version: 1,
        key: schemas().into_iter().flat_map(|s| s.key).collect(),
    }
}
